formula.en:
happy_words = ["good", "great", "love", "tasty", "fast", "friendly"]
sad_words = ["bad", "slow", "cold", "late", "rude", "dirty"]

reviews = [
    "The food was tasty and the staff were friendly",
    "Delivery was late and the food was cold",
    "Good taste but slow service",
]

for review in reviews:
    words = review.lower().split()
    score = 0
    for w in words:
        if w in happy_words:
            score = score + 1
        if w in sad_words:
            score = score - 1
    if score > 0:
        mood = "positive"
    elif score < 0:
        mood = "negative"
    else:
        mood = "neutral"
    print(review, "->", "score", score, "->", mood)

